/bin/sh -lc "python - <<'PY'
from itertools import permutations,combinations
cols='RGB'
target={'R':4,'G':3,'B':3}
for S,D in permutations(cols,2):
 Q=({'R','G','B'}-{S,D}).pop()
 for u,v in combinations(cols,2):
  labels={c:c for c in cols}; labels[u],labels[v]=labels[v],labels[u]
  c={x:0 for x in cols}
  for x in [S,D,D,S,u,v,labels[S],labels[Q],labels[Q],labels[S]]:c[x]+=1
  if c==target: print(S,D,Q,u+v,labels,c)
PY"

